                   if 0<=r+dr<H and 0<=c2+dc<W and g[r+dr][c2+dc]!=bg)
            if n==1:
                for i2 in range(max(0,r-1),min(H,r+2)):
                    for j2 in range(max(0,c2-1),min(W,c2+2)):
                        if o[i2][j2]!=g[r][c2]: o[i2][j2]=3
